contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && balanceAfter == balanceBefore && depositsAfter == depositsBefore)
            || (!reverted && balanceBefore >= v && balanceAfter == balanceBefore - v && depositsAfter == depositsBefore)
        );
    }
}

